CREATE FUNCTION public.check_study_references() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r record; p jsonb; k text; ref text; expected text; BEGIN IF TG_TABLE_NAME='study_items' THEN SELECT * INTO r FROM study_items WHERE id=NEW.id AND user_id=NEW.user_id; IF NOT FOUND THEN RETURN NULL; END IF; p:=r.payload; FOR k,expected IN SELECT * FROM (VALUES ('contest_id','contest'),('subject_id','subject'),('topic_id','topic'),('parent_id','topic')) v(k,expected) LOOP ref:=p->>k; IF ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM study_items WHERE id=ref::uuid AND user_id=NEW.user_id AND kind=expected) THEN RAISE EXCEPTION 'Referência inválida: %',k; END IF; END LOOP; IF r.kind='topic' AND p->>'parent_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM study_items WHERE id=(p->>'parent_id')::uuid AND payload->>'subject_id'=p->>'subject_id' AND id<>r.id) THEN RAISE EXCEPTION 'Subtópico inválido'; END IF; IF r.kind IN ('questions','mock') AND p->>'subject_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM study_items WHERE id=(p->>'subject_id')::uuid AND payload->>'contest_id'=p->>'contest_id') THEN RAISE EXCEPTION 'Disciplina não pertence ao concurso'; END IF; IF r.kind IN ('questions','mock') AND p->>'topic_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM study_items WHERE id=(p->>'topic_id')::uuid AND payload->>'subject_id'=p->>'subject_id') THEN RAISE EXCEPTION 'Tópico não pertence à disciplina'; END IF; IF r.kind='link' THEN FOR ref IN SELECT jsonb_array_elements_text(p->'topic_ids') LOOP IF NOT EXISTS(SELECT 1 FROM study_items WHERE id=ref::uuid AND user_id=NEW.user_id AND kind='topic') THEN RAISE EXCEPTION 'Equivalência contém tópico inválido'; END IF; END LOOP; END IF; ELSE SELECT * INTO r FROM study_sessions WHERE id=NEW.id AND user_id=NEW.user_id; IF NOT FOUND THEN RETURN NULL; END IF; IF cardinality(r.contest_ids)=0 OR EXISTS(SELECT 1 FROM unnest(r.contest_ids) c WHERE NOT EXISTS(SELECT 1 FROM study_items WHERE id=c AND user_id=r.user_id AND kind='contest')) OR NOT EXISTS(SELECT 1 FROM study_items WHERE id=r.subject_id AND user_id=r.user_id AND kind='subject' AND (payload->>'contest_id')::uuid=ANY(r.contest_ids)) THEN RAISE EXCEPTION 'Sessão contém referência inválida'; END IF; IF r.topic_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM study_items WHERE id=r.topic_id AND user_id=r.user_id AND kind='topic' AND payload->>'subject_id'=r.subject_id::text) THEN RAISE EXCEPTION 'Tópico inválido na sessão'; END IF; IF r.finished_at IS NOT NULL AND r.finished_at<r.started_at THEN RAISE EXCEPTION 'Datas da sessão inválidas'; END IF; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER study_item_references AFTER INSERT OR UPDATE ON public.study_items DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_study_references();
CREATE CONSTRAINT TRIGGER study_session_references AFTER INSERT OR UPDATE ON public.study_sessions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_study_references();
CREATE OR REPLACE FUNCTION public.restore_studies(items jsonb, sessions jsonb DEFAULT '[]') RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE x jsonb; n integer:=0; k integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF; IF jsonb_typeof(items)<>'array' OR jsonb_typeof(sessions)<>'array' THEN RAISE EXCEPTION 'Backup inválido'; END IF; FOR x IN SELECT value FROM jsonb_array_elements(items) LOOP INSERT INTO study_items(id,user_id,kind,payload,created_at) VALUES((x->>'id')::uuid,auth.uid(),x->>'kind',x->'payload',coalesce((x->>'created_at')::timestamptz,now())) ON CONFLICT(id) DO NOTHING; GET DIAGNOSTICS k=ROW_COUNT; n:=n+k; IF NOT EXISTS(SELECT 1 FROM study_items WHERE id=(x->>'id')::uuid AND user_id=auth.uid() AND kind=x->>'kind') THEN RAISE EXCEPTION 'Colisão de identificadores no backup'; END IF; END LOOP; FOR x IN SELECT value FROM jsonb_array_elements(sessions) LOOP IF x->>'state'<>'finished' THEN RAISE EXCEPTION 'Sessões ativas não podem ser restauradas'; END IF; INSERT INTO study_sessions(id,user_id,contest_ids,subject_id,topic_id,state,started_at,running_since,elapsed_seconds,finished_at,pauses,notes) VALUES((x->>'id')::uuid,auth.uid(),ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(x->'contest_ids')),(x->>'subject_id')::uuid,(x->>'topic_id')::uuid,'finished',(x->>'started_at')::timestamptz,NULL,(x->>'elapsed_seconds')::numeric,(x->>'finished_at')::timestamptz,coalesce(x->'pauses','[]'),coalesce(x->>'notes','')) ON CONFLICT(id) DO NOTHING; GET DIAGNOSTICS k=ROW_COUNT; n:=n+k; IF NOT EXISTS(SELECT 1 FROM study_sessions WHERE id=(x->>'id')::uuid AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Colisão de identificadores no backup'; END IF; END LOOP; RETURN n; END $$;